class Solution {
    unordered_map<string, bool> memo;
public:
    bool isScramble(string s1, string s2) {
        if (s1 == s2) return true;
        string key = s1 + "#" + s2;
        if (memo.count(key)) return memo[key];
        string c1 = s1, c2 = s2;
        sort(c1.begin(), c1.end());
        sort(c2.begin(), c2.end());
        if (c1 != c2) return memo[key] = false;
        int n = s1.size();
        for (int i = 1; i < n; i++) {
            if ((isScramble(s1.substr(0, i), s2.substr(0, i)) && isScramble(s1.substr(i), s2.substr(i))) ||
                (isScramble(s1.substr(0, i), s2.substr(n - i)) && isScramble(s1.substr(i), s2.substr(0, n - i)))) {
                return memo[key] = true;
            }
        }
        return memo[key] = false;
    }
};

class Solution {
    private java.util.Map<String, Boolean> memo = new java.util.HashMap<>();
    public boolean isScramble(String s1, String s2) {
        if (s1.equals(s2)) return true;
        String key = s1 + "#" + s2;
        if (memo.containsKey(key)) return memo.get(key);
        char[] a1 = s1.toCharArray();
        char[] a2 = s2.toCharArray();
        java.util.Arrays.sort(a1);
        java.util.Arrays.sort(a2);
        if (!new String(a1).equals(new String(a2))) {
            memo.put(key, false);
            return false;
        }
        int n = s1.length();
        for (int i = 1; i < n; i++) {
            if ((isScramble(s1.substring(0, i), s2.substring(0, i)) && isScramble(s1.substring(i), s2.substring(i))) ||
                (isScramble(s1.substring(0, i), s2.substring(n - i)) && isScramble(s1.substring(i), s2.substring(0, n - i)))) {
                memo.put(key, true);
                return true;
            }
        }
        memo.put(key, false);
        return false;
    }
}

/**
 * @param {string} s1
 * @param {string} s2
 * @return {boolean}
 */
var isScramble = function(s1, s2) {
    const memo = new Map();
    function dfs(a, b) {
        if (a === b) return true;
        const key = a + '#' + b;
        if (memo.has(key)) return memo.get(key);
        const sa = a.split('').sort().join('');
        const sb = b.split('').sort().join('');
        if (sa !== sb) {
            memo.set(key, false);
            return false;
        }
        const n = a.length;
        for (let i = 1; i < n; i++) {
            if ((dfs(a.slice(0, i), b.slice(0, i)) && dfs(a.slice(i), b.slice(i))) ||
                (dfs(a.slice(0, i), b.slice(n - i)) && dfs(a.slice(i), b.slice(0, n - i)))) {
                memo.set(key, true);
                return true;
            }
        }
        memo.set(key, false);
        return false;
    }
    return dfs(s1, s2);
};
